// Keep the trusted multiplayer engine identical to the supplied single-player rules.
import ts from "../games/blackjack-3d/node_modules/typescript/lib/typescript.js";
import { readFileSync, writeFileSync } from "node:fs";
for (const [source, target] of [
  ["shared/core", "blackjack-core"],
  ["src/engine", "blackjack-engine"],
]) {
  const input = readFileSync(
    new URL(`../games/blackjack-3d/${source}.ts`, import.meta.url),
    "utf8",
  );
  const output =
    "// Generated by scripts/build-blackjack-server.mjs; edit the TypeScript source.\n" +
    ts
      .transpile(input, {
        target: ts.ScriptTarget.ES2022,
        module: ts.ModuleKind.ES2022,
      })
      .replace("'../shared/core'", "'./blackjack-core.js'");
  const path = new URL(`../functions/${target}.js`, import.meta.url);
  if (process.argv.includes("--check")) {
    // Git may check generated files out with CRLF on Windows.
    if (readFileSync(path, "utf8").replace(/\r\n/g, "\n") !== output.replace(/\r\n/g, "\n"))
      throw Error(`${target} is stale`);
  } else writeFileSync(path, output);
}
